                        code=self._final_code(op.cell_id, op.code),
                        name=op.name or "",
                        config=config,
                        before=op.before,
                        after=op.after,
                    )
                )
            elif isinstance(op, _DeleteOp):
                tx_ops.append(DeleteCell(cell_id=op.cell_id))
            elif isinstance(op, _UpdateOp):
                target_id = op.new_cell_id or op.cell_id
                if op.code is not None:
                    tx_ops.append(
                        SetCode(
                            cell_id=target_id,
                            code=self._final_code(target_id, op.code),
                        )
                    )
